    pcall(function() firetouchinterest(M.root(), b, 0) task.wait(0.1) firetouchinterest(M.root(), b, 1) end)
end
function F.belt()
    local plot = M.plot()
    local tm = plot and plot:FindFirstChild("Treadmill")
    local belt = tm and tm:FindFirstChild("Belt")
    local front = tm and (tm:FindFirstChild("FrontCover") or tm:FindFirstChild("Console") or tm:FindFirstChild("Handle"))
    if not (belt and front) then return nil end
    local fwd = Vector3.new(front.Position.X - belt.Position.X, 0, front.Position.Z - belt.Position.Z)
    return belt, fwd.Magnitude > 0 and fwd.Unit or Vector3.new(0, 0, -1)
end
function F.train()
    if M.attr("OnTreadmill") == true or M.attr("CarryingCage") then return end
    if not F.ready("traingo", 4) then return end
    local belt = F.belt()
    if not belt then S.trainNote = "No treadmill found" return end
    S.task = __T["Going to your treadmill"]
    M.glideTo(belt.Position, 1.2, 25)
end
F.trainHeld = false
track(RunService.Heartbeat:Connect(function()
    local h = M.hum()
    if not h then return end
    if not on("at_on") or M.moving or M.attr("OnTreadmill") ~= true then
        if F.trainHeld then F.trainHeld = false pcall(function() h:Move(Vector3.zero, false) end) end
        return
    end
    local belt, fwd = F.belt()
    local r = M.root()
    if not (belt and r) then return end
    local off = Vector3.new(r.Position.X - belt.Position.X, 0, r.Position.Z - belt.Position.Z)
    pcall(function() h:Move(off:Dot(fwd) > 1.5 and Vector3.zero or fwd, false) end)
    F.trainHeld = true
    S.task = __T["Training on your treadmill"]
end))
function F.upgrades()
    local cash = M.num("Cash")
    local plot = M.plot()
    if on("up_tread") and plot and F.ready("tread", 0.4) then
        local lvl = tonumber(plot:GetAttribute("TreadmillLevel")) or 1
        local cost
        if CF.Tread.GetNextCost then local ok, c = pcall(CF.Tread.GetNextCost, lvl, M.attr("BestWorld", 1), M.attr("DailyBiome", 1)) if ok then cost = tonumber(c) end end
        if cost and cash >= cost then fire("UpgradeTreadmill") S.task = __T["Upgraded treadmill"] cash -= cost end
    end
    if on("up_barn") and plot and F.ready("barn", 0.4) then
        local lvl = tonumber(plot:GetAttribute("Level")) or 1
        local nx = (CF.Plot.Levels or {})[lvl + 1]
        if nx and cash >= (nx.Cost or math.huge) then fire("UpgradePlot") S.task = __T["Upgraded barn"] cash -= nx.Cost
        elseif not nx and CF.Plot.SecondBarn and F.ready("barn2", 4) then
            local l2 = tonumber(plot:GetAttribute("Level2")) or 0
            local n2 = (CF.Plot.SecondBarn.Levels or {})[l2 + 1]
            if n2 and cash >= (n2.Cost or math.huge) then fire("UpgradeBarn2") S.task = __T["Upgraded barn 2"] end
        end
    end
end
function F.rebirth()
    if not F.ready("reb", 3) or M.attr("CarryingCage") then return end
    local reb = M.num("Rebirths")
    if CF.Reb.Count then local ok, c = pcall(CF.Reb.Count, lp) if ok and tonumber(c) then reb = c end end
    local cost
    if CF.Reb.GetCost then local ok, c = pcall(CF.Reb.GetCost, reb + 1, M.attr("BestWorld", 1)) if ok then cost = tonumber(c) end end
    if not cost then S.rebNote = "Max rebirth for this world" return end
    local need = CF.Reb.GetBiome and select(2, pcall(CF.Reb.GetBiome, reb + 1))
    need = tonumber(need)
    S.rebNote = string.format("Rebirth %d: $%s%s", reb + 1, M.fmt(cost), need and (" · reach biome " .. need) or "")
    if M.num("Cash") >= cost and (not need or M.num("DailyBiome") >= need) then
        fire("Rebirth") S.task = __T["Rebirthing"]
    end
end
function F.rewards()
    if on("rw_daily") and M.attr("DailyReady") == true and F.ready("daily", 20) then fire("ClaimDaily") say(__T["Daily reward claimed"]) end
    if on("rw_time") and F.ready("time", 15) then
        local got = {}
        for n in tostring(M.attr("TimeClaimed", "")):gmatch("%d+") do got[tonumber(n)] = true end
        local mins = (CF.Time.Rewards and #CF.Time.Rewards) or 7
        for i = 1, math.max(7, mins) do if not got[i] then fire("ClaimTimeReward", i) break end end
    end
    if on("rw_index") and F.ready("index", 30) then fire("ClaimAllIndexRewards") end
end
function F.candyShop()
    if not F.ready("candy", 4) then return end
    local want = multi("hw_buy")
    if next(want) == nil then return end
    local items = (CF.Hw.Shop or {}).Items or {}
    for _, it in ipairs(items) do
        local key = it.Key or it.Id or it.Name
        if key and want[it.Name or key] and M.num("Candy") >= (it.Price or math.huge) then
            if not M.goShop("HalloweenShop", ((CF.Hw.Shop or {}).Ring or 11) + 2) then S.brewNote = "Go to the Candy shop" return end
            fire("BuyCandyItem", key) S.task = __T["Bought "] .. tostring(it.Name or key) return
        end
    end
end
function F.potion()
    if not F.ready("potion", 3) or M.attr("CarryingCage") then return end
    local bp, ch, h = lp:FindFirstChild("Backpack"), lp.Character, M.hum()
    if not (bp and ch and h) then return end
    local tool
    for _, t in ipairs(bp:GetChildren()) do if t:IsA("Tool") and t:GetAttribute("PotionKind") then tool = t break end end
    if not tool then return end
    local prev = ch:FindFirstChildOfClass("Tool")
    pcall(function() h:EquipTool(tool) end)
    task.wait(0.3)
    fire("DrinkPotion")
    task.wait(0.4)
    if prev and prev.Parent then pcall(function() h:EquipTool(prev) end) else pcall(function() h:UnequipTools() end) end
    S.task = __T["Drank a potion"]
end
function F.trail()
    if not F.ready("trail", 3) then return end
    local owned = lp:FindFirstChild("Trails")
    local top, topB = nil, -1
    for key, t in pairs(CF.Trail.Trails or {}) do
        if type(t) == "table" and owned and owned:FindFirstChild(key) and (t.Treadmill or 1) > topB then top, topB = key, t.Treadmill or 1 end
    end
    local best, bestB = nil, topB
    for key, t in pairs(CF.Trail.Trails or {}) do
        if type(t) == "table" and tonumber(t.Price) and not (owned and owned:FindFirstChild(key)) and M.num("Cash") >= t.Price and (t.Treadmill or 1) > bestB then best, bestB = key, t.Treadmill or 1 end
    end
    if best then
        if not M.goShop("TrailShop", (CF.Trail.ShopRadius or 5) + 3) then S.trailNote = "Go to the Trail shop" return end
        if M.num("Cash") < (CF.Trail.Trails[best].Price or math.huge) then return end
        fire("BuyTrail", best)
        task.wait(0.6)
        if owned and owned:FindFirstChild(best) then S.task = __T["Bought trail "] .. best end
        return
    end
    if top and M.attr("Trail") ~= top then fire("EquipTrail", top) S.task = __T["Equipped trail "] .. top end
end
local ST = { EDGE = 2, REACH_LIMIT = 8, SPEED_RATIO = 3.3, skip = setmetatable({}, { __mode = "k" }), pathSkip = {}, stat = {}, bossSeen = {}, events = {}, recent = {}, escaped = 0, caught = 0, lost = 0, best = "-" }
do
    local function char() return lp.Character end
