    end
    onClean(function() ST.quiet(false) end)
    function ST.respawnTo(pos)
        local c0, r0, h0 = char(), hrp(), hum()
        if not (c0 and r0 and h0) or h0.Health <= 0 then return false end
        pcall(function()
            local animate = c0:FindFirstChild("Animate")
            local animator = h0:FindFirstChildOfClass("Animator")
            if animator then for _, tr in ipairs(animator:GetPlayingAnimationTracks()) do pcall(function() tr:AdjustSpeed(0) end) end end
            if animate then animate.Disabled = true end
            h0.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
        end)
        local stand = r0.CFrame
        local pose = {}
        for _, p in ipairs(c0:GetDescendants()) do if p:IsA("BasePart") then pose[p] = stand:ToObjectSpace(p.CFrame) end end
        local held = {}
        local function release() for _, x in ipairs(held) do pcall(function() x:Disconnect() end) end held = {} end
        local function still()
            for p, off in pairs(pose) do
                if p.Parent then p.CFrame = stand * off p.AssemblyLinearVelocity = Vector3.zero p.AssemblyAngularVelocity = Vector3.zero end
            end
        end
        held[#held + 1] = RunService.Stepped:Connect(still)
        held[#held + 1] = RunService.Heartbeat:Connect(still)
        held[#held + 1] = c0.DescendantAdded:Connect(function(x)
            if x:IsA("BallSocketConstraint") or x:IsA("HingeConstraint") then pcall(function() x.Enabled = false end)
