    local RP = RaycastParams.new()
    RP.FilterType = Enum.RaycastFilterType.Exclude
    RP.RespectCanCollide = true
    function ST.glide(pos, mult, stopWhen)
        local r, h = hrp(), hum()
        if not (r and h) then return false end
        local a = r.Position
        local hip = h.HipHeight + r.Size.Y / 2
        local dist = (flat(pos) - flat(a)).Magnitude
        local moved, y = 0, a.Y
        local c0 = char()
        while RUNNING and moved < dist do
            local dt = RunService.Heartbeat:Wait()
            r = hrp()
            if not r or char() ~= c0 then return false end
            if stopWhen and stopWhen() then return false end
            local speed = (hum() and hum().WalkSpeed or 16) * (mult or 1)
            moved = math.min(dist, moved + speed * dt)
            local p = a:Lerp(pos, moved / math.max(dist, 0.01))
            RP.FilterDescendantsInstances = { char() }
            local g = Workspace:Raycast(Vector3.new(p.X, y + 60, p.Z), Vector3.new(0, -120, 0), RP)
            if not g then return false end
            y = y + math.clamp(g.Position.Y + hip - y, -2, 2)
            local here = Vector3.new(p.X, y, p.Z)
            local dir = flat(pos) - flat(a)
            dir = dir.Magnitude > 0.01 and dir.Unit or Vector3.new(0, 0, 1)
            r.CFrame = CFrame.lookAt(here, here + dir)
            r.AssemblyLinearVelocity = dir * speed
            local hh = hum()
            if hh and hh:GetState() == Enum.HumanoidStateType.Freefall then pcall(function() hh:ChangeState(Enum.HumanoidStateType.Running) end) end
        end
