    end
    function ST.pathNum(path) return tonumber(tostring(path.Name):match("%d+")) end
    function ST.cagePrompt(c) local p = c:FindFirstChildWhichIsA("ProximityPrompt", true) return p and p.Enabled and p or nil end
    function ST.cageKind(c) return c:GetAttribute("Kind") or tostring(c.Name):gsub("Cage$", "") end
    function ST.cageOpen(c)
