    local STAT_FILE = "COMBO_WICK_PETRIDE/paths_" .. tostring(lp.UserId) .. ".json"
    local BOSS_FILE = "COMBO_WICK_PETRIDE/bosses.json"
    local function save(file, t) pcall(function() if writefile then if makefolder and not isfolder("COMBO_WICK_PETRIDE") then makefolder("COMBO_WICK_PETRIDE") end writefile(file, HttpService:JSONEncode(t)) end end) end
    pcall(function() if isfile and isfile(STAT_FILE) then ST.stat = HttpService:JSONDecode(readfile(STAT_FILE)) or {} end end)
    function ST.pathResult(n, okTrip)
