        if okTrip then s.ok += 1 s.streak = 0
        else s.miss += 1 s.streak += 1 s.ws = ST.ws() s.at = os.time() end
        ST.stat[k] = s
        save(STAT_FILE, ST.stat)
    end
    function ST.pathTooHard(n)
