    for n, v in ipairs({ { 22, "GrandpaGus" }, { 31, "QueenBee" }, { 39, "GorillaChief" }, { 44, "MamaRex" }, { 52, "Yeti" }, { 64, "MummyKing" }, { 77, "GingerbreadGiant" }, { 84, "LavaDragon" }, { 101, "StormTitan" }, { 117, "AlienEmperor" } }) do ST.bossSeen[n] = { chase = v[1], kind = v[2] } end
    pcall(function()
        if isfile and isfile(BOSS_FILE) then
