        if not (r and sz) then return false end
        local here = r.Position
        local floor = ST.wallFloor(here.Z, here.X)
        local cx, half = floor and floor.Position.X or sz.Position.X, floor and floor.Size.X / 2 or 80
        local sgn = (here.X >= cx) and 1 or -1
        local edgeX = cx + sgn * (half + ST.EDGE)
        local zEdge = sz.Position.Z - sz.Size.Z / 2
        local lost = function() return not ST.carrying() end
        S.task = __T["Bringing "] .. tostring(lp:GetAttribute("CarryingCage") or __T["cage"]) .. __T[" home"]
        if not ST.glide(Vector3.new(edgeX, 0, here.Z + 4), 1, lost) then return false end
        if not ST.glide(Vector3.new(edgeX, 0, zEdge + 6), 1, lost) then return false end
        RP.FilterDescendantsInstances = { char() }
