        local kind = ST.cageKind(c)
        local wall = ST.wallSpot(cp.Z, cp.X)
        if not wall then ST.skip[c] = os.clock() + 30 return false end
        if not on("st_on") then return false end
        S.task = __T["Going for a "] .. kind .. __T[" cage"]
        local r = hrp()
        if r and (r.Position - wall).Magnitude > 40 then
            if not ST.respawnTo(wall) then return false end
            task.wait(0.4)
        elseif r then
            ST.glide(wall, 1)
        end
        ST.ride() task.wait(0.3)
        local tw = os.clock()
        while RUNNING and not ST.cagePrompt(c) and c.Name ~= "Held" and os.clock() - tw < 3 do task.wait(0.1) end
        if not ST.cagePrompt(c) then ST.skip[c] = os.clock() + 20 return false end
        cp = c:GetPivot().Position
        if not on("st_on") then return ST.abort() end
        ST.glide(Vector3.new(cp.X, 0, cp.Z + 4), 1, function() return not on("st_on") end)
        if not on("st_on") then return ST.abort() end
        ST.events.BossCaught, ST.events.Escaped = nil, nil
        local streak0 = tonumber(lp:GetAttribute("EscapeStreak")) or 0
        local bag = lp:FindFirstChild("Cages")
        local bag0 = bag and #bag:GetChildren() or 0
        if not ST.steal(c) then ST.skip[c] = os.clock() + 15 say(__T["Couldn't grab it"]) return false end
        LOG("stole", kind, "path", pathN)
        local lost = function() return not ST.carrying() end
        ST.glide(Vector3.new(wall.X, 0, wall.Z), 1, lost)
        if ST.carrying() then
            local z0 = hrp() and hrp().Position.Z or wall.Z
            ST.glide(Vector3.new(wall.X, 0, math.min(z0 + 80, -56)), 1, lost)
            ST.home()
        end
        local t0 = os.clock()
        while RUNNING and ST.carrying() and os.clock() - t0 < 3 do task.wait(0.1) end
        local t1 = os.clock()
        while RUNNING and not (ST.events.Escaped or ST.events.BossCaught) and os.clock() - t1 < 1.5 do task.wait(0.05) end
        local streak1 = tonumber(lp:GetAttribute("EscapeStreak")) or 0
        local gotHome = ST.events.Escaped or streak1 > streak0 or (bag and #bag:GetChildren() > bag0)
        if gotHome and not ST.carrying() and not ST.events.BossCaught then
            ST.pathResult(pathN, true)
            ST.escaped += 1
            if (ST.KINDS[kind] or 0) > (ST.KINDS[ST.best] or 0) then ST.best = kind end
            say(kind .. __T[" cage brought home"])
            return true
        elseif ST.events.BossCaught then
            ST.pathResult(pathN, false)
            ST.caught += 1
            say(__T["A boss caught you · skipping that path for a bit"])
            ST.pathSkip[pathN] = os.clock() + 90
        else
            ST.lost += 1
            LOG("lost on path", pathN, table.concat(ST.recent, " "))
        end
        return false
    end
    task.spawn(function()
        while RUNNING do
            pcall(function()
                ST.quiet(on("st_on") == true)
                local h = hum()
                if not on("st_on") or S.staff or not h or h.Health <= 0 or ST.respawning then return end
                if S.newBuild and on("sf_pause") and not ST.carrying() then S.task = __T["Paused: the game updated"] return end
                if ST.carrying() then
                    if M.moving and M.moving ~= "steal" then return end
                    M.moving = "steal"
                    pcall(ST.home)
                    M.moving = false
                    return
                end
                if ST.nightSoon() then S.task = __T["Night is coming · waiting in the safe zone"] return end
                if M.moving then return end
                local c = ST.pick()
                if not c then S.task = __T["Waiting for a cage on your paths"] return end
                M.moving = "steal"
                local ok, res = pcall(ST.trip, c)
                if not ok then LOG("trip", res) end
                if (not ok or res == false) and not ST.carrying() and lp:GetAttribute("InSafeZone") ~= true and on("st_on") then pcall(ST.abort) task.wait(1) end
                M.moving = false
            end)
            task.wait(0.3)
        end
    end)
    local GREEN, YELLOW, GRAY, RED = "#7CFC8A", "#F5C542", "#9AA0A6", "#FF6B6B"
    function ST.col(c, t) return '<font color="' .. c .. '">' .. t .. "</font>" end
    ST.C = { GREEN = GREEN, YELLOW = YELLOW, GRAY = GRAY, RED = RED }
    function ST.bossName(n)
        local info = ST.bossSeen[n]
        local b = info and info.kind and ST.BOSS.Bosses and ST.BOSS.Bosses[info.kind]
        return (b and b.Name) or (info and info.kind) or "?"
    end
    function ST.pathState(n)
        local info = ST.bossInfo(n)
        if not info then return "unknown", "?" end
        if ST.reachOf(info) >= ST.REACH_LIMIT then return "never", "never" end
        local need = math.ceil(info.chase / ST.SPEED_RATIO)
        if ST.ws() < need then return "need", need .. " speed", need end
        if ST.pathTooHard(n) then return "rest", "resting" end
        return "ready", "ready"
    end
    function ST.pathLines()
        local lines, goal = {}, nil
        for n = 1, 10 do
            local st, txt, need = ST.pathState(n)
            local c = (st == "ready" and GREEN) or (st == "rest" and YELLOW) or (st == "never" and RED) or GRAY
            lines[#lines + 1] = ST.col(c, string.format("%d · %s · %s", n, ST.bossName(n), txt))
            if st == "need" and (not goal or need < goal.need) then goal = { n = n, need = need } end
        end
        return table.concat(lines, "\n"), goal
    end
end
