function E.make(model, color, text)
    local root = model:FindFirstChild("Root") or model:FindFirstChildWhichIsA("BasePart", true)
    if not root then return end
    local hl = Instance.new("Highlight")
    hl.FillColor, hl.OutlineColor, hl.FillTransparency, hl.OutlineTransparency = color, color, 0.6, 0
    hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    hl.Adornee = model
    local bb = Instance.new("BillboardGui")
    bb.Size = UDim2.fromOffset(170, 34) bb.AlwaysOnTop = true bb.StudsOffset = Vector3.new(0, 4, 0) bb.Adornee = root bb.MaxDistance = 100000
    local tl = Instance.new("TextLabel")
    tl.Size = UDim2.fromScale(1, 1) tl.BackgroundTransparency = 1 tl.TextColor3 = color tl.TextStrokeTransparency = 0.3 tl.Font = Enum.Font.GothamBold tl.TextScaled = true tl.Text = text
    tl.Parent = bb
    local parent = (gethui and gethui()) or game:GetService("CoreGui")
    hl.Parent = parent bb.Parent = parent
    E.objs[model] = { hl, bb, tl }
end
function E.tick()
    local want = multi("esp_rar")
    local onE = on("esp_on")
    local seen = {}
    local r = M.root()
    local best
    local P2 = Workspace:FindFirstChild("Paths")
    if onE and P2 then
        for _, path in ipairs(P2:GetChildren()) do
            local cg = path:FindFirstChild("Cages")
            if cg then for _, c in ipairs(cg:GetChildren()) do
                local kind = c:GetAttribute("Kind")
                if kind and (next(want) == nil or want[kind]) then
                    seen[c] = true
                    local d = ""
                    if r then local ok, p = pcall(function() return c:GetPivot().Position end) if ok then d = " · " .. math.floor((p - r.Position).Magnitude) .. "m" end end
                    local txt = kind .. " · P" .. tostring(c:GetAttribute("Path") or "?") .. d
                    local o = E.objs[c]
                    if not o then E.make(c, E.colors[kind] or Color3.new(1, 1, 1), txt) else pcall(function() o[3].Text = txt end) end
                    if not best or (RANK[kind] or 0) > (RANK[best] or 0) then best = kind end
                end
            end end
        end
    end
    for m in pairs(E.objs) do if not seen[m] or not m.Parent then E.clear(m) end end
    S.bestCage = best
end
onClean(function() for m in pairs(E.objs) do E.clear(m) end end)
