task.spawn(function()
    S.cash0 = M.num("Cash")
    while RUNNING do
        pcall(function()
            local pets, cages = M.pets(), M.cages()
            local inPen, earn = 0, 0
            for _, p in ipairs(pets) do if p.stall then inPen += 1 earn += p.inc end end
            local stalls = #M.stalls()
            setText(UI.s1, string.format(__T["Cash $%s · Gems %s · Candy %s"], M.fmt(M.num("Cash")), M.fmt(M.num("Gems")), M.fmt(M.num("Candy"))))
            setText(UI.s2, string.format(__T["Pens %d/%d · ~$%s/s · Rebirths %d"], inPen + (function() local n = 0 for _, c in ipairs(cages) do if c.stall then n += 1 end end return n end)(), stalls, M.fmt(earn), M.num("Rebirths")))
            setText(UI.s3, S.staff and (__T["Paused: staff "] .. S.staff) or (__T["Doing: "] .. S.task))
            local g = (os.clock() - S.msgAt < 8 and S.msg ~= "") and S.msg or ((os.clock() - S.gmsgAt < 8 and S.gmsg ~= "") and ("Game: " .. S.gmsg) or "")
            setText(UI.s4, g)
            local now, nxt, waiting = M.now(), nil, 0
            for _, c in ipairs(cages) do if c.stall and c.ready then if c.ready > now then nxt = math.min(nxt or math.huge, c.ready - now) end else waiting += c.stall and 0 or 1 end end
            local inv = 0 for _, c in ipairs(cages) do if not c.stall then inv += 1 end end
            setText(UI.cg, string.format(__T["Opened %d · Placed %d · %d cages waiting%s"], S.opened, S.placed, inv, nxt and (__T[" · next opens in "] .. M.eta(nxt)) or ""))
            setText(UI.pn, string.format(__T["%d pets · %d in pens%s"], #pets, inPen, (S.penNote and not on("walk_on")) and (" · " .. S.penNote) or ""))
            setText(UI.fu, (S.fuseNote or "") .. (S.fused > 0 and (__T[" · fused "] .. S.fused) or ""))
            setText(UI.sl, (S.sellNote or "") .. (S.sold > 0 and (__T[" · sold "] .. S.sold) or ""))
            local plot = M.plot()
            if plot then
                local tl = tonumber(plot:GetAttribute("TreadmillLevel")) or 1
                local bl = tonumber(plot:GetAttribute("Level")) or 1
                local tc
                if CF.Tread.GetNextCost then local ok, c = pcall(CF.Tread.GetNextCost, tl, M.attr("BestWorld", 1), M.attr("DailyBiome", 1)) if ok then tc = tonumber(c) end end
                local bn = (CF.Plot.Levels or {})[bl + 1]
                setText(UI.tm, string.format(__T["Speed %s · Lv %d%s%s"], M.fmt(M.num("Speed")), tl, tc and (__T[" · next $"] .. M.fmt(tc)) or __T[" · max"], S.taps and (__T[" · boosts "] .. S.taps) or ""))
                setText(UI.up, string.format(__T["Barn Lv %d%s · Trail %s"], bl, bn and (__T[" · next $"] .. M.fmt(bn.Cost)) or __T[" · max"], tostring(M.attr("Trail", "-"))))
            end
            setText(UI.rb, S.rebNote or "")
            local got = 0 for _ in tostring(M.attr("TimeClaimed", "")):gmatch("%d+") do got += 1 end
            setText(UI.rw, string.format(__T["Daily: %s · Time rewards %d/7"], M.attr("DailyReady") == true and "ready" or __T["claimed"], got))
            setText(UI.hw, (S.brewNote or "") .. (S.brewed > 0 and (__T[" · brewed "] .. S.brewed) or ""))
            setText(UI.esp, S.bestCage and (__T["Best cage out: "] .. S.bestCage) or "")
            setText(UI.gs1, __T["Game updated: "] .. (S.updated or __T["checking..."]) .. __T[" · build "] .. S.build)
            setText(UI.gs2, __T["Script checked: "] .. CONFIG.CHECKED .. __T[" · build "] .. CONFIG.BUILD)
            setText(UI.gs3, S.newBuild and '<font color="#F5C542">Game updated after this script. Some features may be broken until the next script update.</font>' or '<font color="#7CFC8A">Script is up to date with this server.</font>')
            local C = ST.C
            local tk = on("st_on") and ((os.clock() - S.msgAt < 4 and S.msg ~= "") and S.msg or S.task) or ST.col(C.GRAY, "Off · turn on Auto Steal Cages")
            setText(UI.st_task, tk)
            local mins = math.max((os.clock() - S.t0) / 60, 0.1)
            setText(UI.st_stats, string.format(__T["Brought home %s · %.1f/min · caught %d"], ST.col(C.GREEN, tostring(ST.escaped)), ST.escaped / mins, ST.caught))
            setText(UI.st_best, __T["Best cage: "] .. (ST.best ~= "-" and ST.col(C.YELLOW, ST.best) or "-"))
            local ws = math.floor(ST.ws())
            setText(UI.st_speed, __T["Your speed "] .. ST.col(C.GREEN, tostring(ws)))
            local lines, goal = ST.pathLines()
            setText(UI.st_paths, lines)
            setText(UI.st_goal, goal and (__T["Next: "] .. ST.col(C.YELLOW, "Path " .. goal.n) .. __T[" at "] .. goal.need .. __T[" speed ("] .. math.max(goal.need - ws, 0) .. __T[" more)"]) or ST.col(C.GREEN, __T["Every path you can do is unlocked"]))
            local bad = {}
            for name in pairs(multi("st_paths")) do
                local n = tonumber(tostring(name):match("%d+"))
                local st, why = ST.pathState(n)
                if st == "need" or st == "never" then bad[#bad + 1] = "Path " .. n .. " (" .. why .. ")" end
            end
            table.sort(bad)
            setText(UI.pickWarn, #bad > 0 and ST.col(C.YELLOW, __T["You'll get caught on: "] .. table.concat(bad, ", ")) or ST.col(C.GREEN, __T["All picked paths are safe for you"]))
        end)
        task.wait(0.5)
    end
end)
