do
    local pending = false
    local function queue()
        if pending or not RUNNING then return end
        pending = true
        task.delay(1.5, function() pending = false; if RUNNING then pcall(function() SaveManager:Save("auto") end) end end)
    end
    local function skip(k) k = tostring(k); return k == "MenuKeybind" or k:find("^ThemeManager") or k:find("^SaveManager") or k:find("Color") or k == "FeedbackMsg" or k == "FeedbackType" end
    task.delay(2, function()
        for k, t in pairs(Toggles) do if not skip(k) then pcall(function() local prev = t.Changed t:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
        for k, o in pairs(Opt) do if not skip(k) then pcall(function() local prev = o.Changed o:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
    end)
end
function UI.center()
    pcall(function()
        local sg = Library.ScreenGui
        local m = sg and sg:FindFirstChild("Main")
        if not m then return end
        m.AnchorPoint = Vector2.zero
        for _ = 1, 3 do
            local vs, sz, cur = sg.AbsoluteSize, m.AbsoluteSize, m.AbsolutePosition
            local tx, ty = math.max(0, math.floor((vs.X - sz.X) / 2)), math.max(0, math.floor((vs.Y - sz.Y) / 2))
            local k = (m.Size.X.Offset > 0 and sz.X / m.Size.X.Offset) or 1
            if math.abs(cur.X - tx) < 2 and math.abs(cur.Y - ty) < 2 then break end
            m.Position = UDim2.new(m.Position.X.Scale, m.Position.X.Offset + (tx - cur.X) / k, m.Position.Y.Scale, m.Position.Y.Offset + (ty - cur.Y) / k)
            RunService.Heartbeat:Wait()
        end
    end)
end
for _, d in ipairs({ 1, 3, 6 }) do task.delay(d, UI.center) end
